      "keystrokes": "cat > src/memory.py << 'EOF'
import sqlite3
import os
from pathlib import Path
from datetime import datetime

class AgentMemory:
    def __init__(self, db_path=None):
        if db_path is None:
            db_path = Path.home() / '.agent-memory' / 'memory.db'
        self.db_path = Path(db_path)
        self.db_path.parent.mkdir(parents=True, exist_ok=True)
        self._init_db()

    def _get_conn(self):
        return sqlite3.connect(self.db_path)

    def _init_db(self):
        with self._get_conn() as conn:
            conn.execute('''CREATE TABLE IF NOT EXISTS facts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                content TEXT NOT NULL,
                tags TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )''')
            conn.execute('''CREATE TABLE IF NOT EXISTS lessons (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                action TEXT,
                context TEXT,
                outcome TEXT,
                insight TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )''')
            conn.execute('''CREATE TABLE IF NOT EXISTS entities (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                entity_type TEXT,
                attributes TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )''')

    def remember(self, content, tags=None):
        with self._get_conn() as conn:
            tags_json = str(tags) if tags else None
            conn.execute(
                'INSERT INTO facts (content, tags) VALUES (?, ?)',
                (content, tags_json)
            )
            conn.commit()

    def learn(self, action, context, outcome, insight):
        with self._get_conn() as conn:
            conn.execute(
                'INSERT INTO lessons (action, context, outcome, insight) VALUES (?, ?, ?, ?)',
                (action, context, outcome, insight)
            )
            conn.commit()

    def recall(self, query=""):
        with self._get_conn() as conn:
            if query:
                cursor = conn.execute(
                    'SELECT content, tags, created_at FROM facts WHERE content LIKE ? ORDER BY created_at DESC',
                    (f'%{query}%',)
                )
            else:
                cursor = conn.execute(
                    'SELECT content, tags, created_at FROM facts ORDER BY created_at DESC'
                )
            return [{'content': r[0], 'tags': r[1], 'created_at': r[2]} for r in cursor.fetchall()]

    def get_lessons(self, context=None, limit=None):
        with self._get_conn() as conn:
            if context:
                cursor = conn.execute(
                    'SELECT action, context, outcome, insight, created_at FROM lessons WHERE context LIKE ? ORDER BY created_at DESC',
                    (f'%{context}%',)
                )
            else:
                cursor = conn.execute(
                    'SELECT action, context, outcome, insight, created_at FROM lessons ORDER BY created_at DESC'
                )
            if limit:
                cursor = conn.execute(
                    f'SELECT action, context, outcome, insight, created_at FROM lessons ORDER BY created_at DESC LIMIT {limit}'
                )
            return [{'action': r[0], 'context': r[1], 'outcome': r[2], 'insight': r[3], 'created_at': r[4]} for r in cursor.fetchall()]

    def track_entity(self, name, entity_type, attributes=None):
        with self._get_conn() as conn:
            attrs_json = str(attributes) if attributes else None
            conn.execute(
                'INSERT INTO entities (name, entity_type, attributes) VALUES (?, ?, ?)',
                (name, entity_type, attrs_json)
            )
            conn.commit()

    def get_entities(self, entity_type=None):
        with self._get_conn() as conn:
            if entity_type:
                cursor = conn.execute(
                    'SELECT name, entity_type, attributes, created_at FROM entities WHERE entity_type = ?',
                    (entity_type,)
                )
            else:
                cursor = conn.execute(
                    'SELECT name, entity_type, attributes, created_at FROM entities'
                )
            return [{'name': r[0], 'entity_type': r[1], 'attributes': r[2], 'created_at': r[3]} for r in cursor.fetchall()]
EOF\n",
      "duration": 0.5
    }
